61: pub fn gather_payload(table: &Mapping, indexed_axis: &Mapping) -> Result<GatherPayload, GatherMappingError> {
62:     // `find_axis` decides the only rule: the region is consecutive. How many axes name it does not
63:     // matter, and an axis the table does not hold at all fails the same call.
64:     let indexed_axis_stride =
65:         table
66:             .find_axis(indexed_axis)
67:             .map_err(|error| GatherMappingError::IndexedAxisNotConsecutive {
68:                 table: table.clone(),
69:                 indexed_axis: indexed_axis.clone(),
70:                 error,
71:             })?;
72:     // A located axis may still be inseparable from its surrounding mapping.
73:     let payload = table
74:         .remove_axis(indexed_axis)
75:         .map_err(|error| GatherMappingError::IndexedAxisNotRemovable {
76:             table: table.clone(),
77:             indexed_axis: indexed_axis.clone(),
78:             error,
79:         })?;
80:     Ok(GatherPayload {
81:         payload: payload.normalize(),
82:         indexed_axis_stride,
83:     })
84: }
