86: /// Checks the payload a kernel declared against the one its table and indexed axis determine.
87: pub fn validate_gather_payload(
88:     table: &Mapping,
89:     indexed_axis: &Mapping,
90:     declared: &Mapping,
91: ) -> Result<GatherPayload, GatherMappingError> {
92:     let derived = gather_payload(table, indexed_axis)?;
93:     let declared_normal = declared.clone().normalize();
94:     if derived.payload != declared_normal {
95:         return Err(GatherMappingError::PayloadMismatch {
96:             table: Box::new(table.clone()),
97:             indexed_axis: Box::new(indexed_axis.clone()),
98:             expected: Box::new(derived.payload),
99:             declared: Box::new(declared_normal),
100:         });
101:     }
102:     Ok(derived)
103: }
